      "arFull": "یَسْـَٔلُوْنَكَ عَنِ الْاَنْفَالِ ؕ قُلِ الْاَنْفَالُ لِلّٰهِ وَالرَّسُوْلِ ۚ فَاتَّقُوا اللّٰهَ وَاَصْلِحُوْا ذَاتَ بَیْنِكُمْ ۪ وَاَطِیْعُوا اللّٰهَ وَرَسُوْلَهٗۤ اِنْ كُنْتُمْ مُّؤْمِنِیْنَ ۟",
      "ur": "یہ لوگ آپ سے غنیمتوں کا حکم دریافت کرتے ہیں[1] ، آپ فرما دیجئے! کہ یہ غنیمتیں اللہ کی ہیں اور رسول کی ہیں[2]، سو تم اللہ سے ڈرو اور اپنے باہمی تعلقات کی اصلاح کرو اور اللہ تعالیٰ اور اس کے رسول کی اطاعت کرو اگر تم ایمان والے ہو۔[3]",
      "en": "They ask you, [O Muḥammad], about the bounties [of war]. Say, \"The [decision concerning] bounties is for Allāh and the Messenger.\" So fear Allāh and amend that which is between you and obey Allāh and His Messenger, if you should be believers.",
      "footnotesUr": "[1] ”أَنْفَالٌ“ نَفَلٌ کی جمع ہے جس کے معنی زیادہ کے ہیں، یہ اس مال واسباب کو کہا جاتا ہے، جو کافروں کے ساتھ جنگ میں ہاتھ لگے، جسے غنیمت بھی کہا جاتا ہے اسے نفل (زیادہ) اس لیے کہا جاتا ہے کہ یہ ان چیزوں میں سے ایک ہے جو پچھلی امتوں پر حرام تھیں۔ یہ گویا امت محمدیہ پر ایک زائد چیز حلال کی گئی ہے یا اس لیے کہ یہ جہاد کے اجر سے (جو آخرت میں ملے گا) ایک زائد چیز ہے جو بعض دفعہ دنیا میں ہی مل جاتی ہے۔\n[2] یعنی اس کا فیصلہ کرنے کے مجاز ہیں۔ اللہ کا رسول، اللہ کے حکم سے اسے تقسیم فرمائے گا۔ نہ کہ تم آپس میں جس طرح چاہو اسے تقسیم کرلو۔\n[3] اس کا مطلب یہ ہوا کہ مذکورہ تینوں باتوں پر عمل کے بغیر ایمان مکمل نہیں۔ اس سے تقویٰ، اصلاح ذات البین اور اللہ اور رسول کی اطاعت کی اہمیت واضح ہے۔ خاص طور پر مال غنیمت کی تقسیم میں ان تینوں امور پر عمل نہایت ضروری ہے۔ کیونکہ مال کی تقسیم میں باہمی فساد کا بھی شدید اندیشہ رہتا ہے، اس کے علاج کے لیے اصلاح ذات البین پر زور دیا۔ ہیراپھیری اور خیانت کا بھی امکاں رہتا ہے اس کے لیے تقویٰ کا حکم دیا۔ اس کے باوجود بھی کوئی کوتاہی ہو جائے تو اس کا حل اللہ اور رسول کی اطاعت میں مضمر ہے۔",
