      "ur": "اور تم لوگ اس وقت کو یاد کرو! جب کہ اللہ تم سے ان دو جماعتوں میں سے ایک کا وعده کرتا تھا کہ وه تمہارے ہاتھ آجائے گی[1] اور تم اس تمنا میں تھے کہ غیر مسلح جماعت تمہارے ہاتھ آجائے[2] اور اللہ تعالیٰ کو یہ منظور تھا کہ اپنے احکام سے حق کا حق ہونا ﺛابت کردے اور ان کافروں کی جڑ کاٹ دے۔",
      "en": "[Remember, O believers], when Allāh promised you one of the two groups[438] - that it would be yours - and you wished that the unarmed one would be yours. But Allāh intended to establish the truth by His words and to eliminate the disbelievers",
