      "number": 11,
      "arFull": "اِذْ یُغَشِّیْكُمُ النُّعَاسَ اَمَنَةً مِّنْهُ وَیُنَزِّلُ عَلَیْكُمْ مِّنَ السَّمَآءِ مَآءً لِّیُطَهِّرَكُمْ بِهٖ وَیُذْهِبَ عَنْكُمْ رِجْزَ الشَّیْطٰنِ وَلِیَرْبِطَ عَلٰی قُلُوْبِكُمْ وَیُثَبِّتَ بِهِ الْاَقْدَامَ ۟ؕ",
      "ur": "اس وقت کو یاد کرو جب کہ اللہ تم پر اونگھ طاری کر رہا تھا اپنی طرف سے چین دینے کے لیے[1] اور تم پر آسمان سے پانی برسا رہا تھا کہ اس پانی کے ذریعہ سے تم کو پاک کر دے اور تم سے شیطانی وسوسہ کو دفع کر دے[2] اور تمہارے دلوں کو مضبوط کر دے اور تمہارے پاؤں جما دے۔[3]",
      "en": "[Remember] when He overwhelmed you with drowsiness [giving] security from Him and sent down upon you from the sky, rain by which to purify you and remove from you the evil [suggestions] of Satan and to make steadfast your hearts and plant firmly thereby your feet.",
      "footnotesUr": "[1] جنگ احد کی طرح جنگ بدر میں بھی اللہ تعالیٰ نے مسلمانوں پر اونگھ طاری کر دی، جس سے ان کے دلوں کے بوجھ ہلکے ہوگئے اور اطمینان وسکون کی ایک خاص کیفیت ان پر طاری ہوگئی ۔\n[2] تیسرا انعام یہ کیا کہ بارش نازل فرما دی، جس سے ایک تو رتیلی زمین میں نقل وحرکت آسان ہوگئی ۔ دوسرے وضو وطہارت میں آسانی ہوگئی ۔ تیسرے اس سے شیطانی وسوسوں کا ازالہ فرما دیا گیا جو وہ اہل ایمان کے دلوں میں ڈال رہا تھا کہ تم اللہ کے نیک بندے ہوتے ہوئے بھی پانی سے دور ہو، دوسرے جنابت کی حالت میں تم لڑو گے تو کیسے اللہ کی رحمت ونصرت تمہیں حاصل ہوگی؟ تیسرے تم پیاسے ہو، جب کہ تمہارے دشمن سیراب ہیں۔ وغیرہ وغیرہ ۔\n[3] یہ چوتھا انعام ہے جو دلوں اور قدموں کو مضبوط کرکے کیا گیا۔",
