      "arFull": "اِذْ یُوْحِیْ رَبُّكَ اِلَی الْمَلٰٓىِٕكَةِ اَنِّیْ مَعَكُمْ فَثَبِّتُوا الَّذِیْنَ اٰمَنُوْا ؕ سَاُلْقِیْ فِیْ قُلُوْبِ الَّذِیْنَ كَفَرُوا الرُّعْبَ فَاضْرِبُوْا فَوْقَ الْاَعْنَاقِ وَاضْرِبُوْا مِنْهُمْ كُلَّ بَنَانٍ ۟ؕ",
