      "en": "[Remember] when your Lord inspired to the angels, \"I am with you, so strengthen those who have believed. I will cast terror into the hearts of those who disbelieved, so strike [them] upon the necks and strike from them every fingertip.\"[439]",
      "footnotesUr": "[1] یہ اللہ تعالیٰ نے فرشتوں کے ذریعے سے اور خاص اپنی طرف سے جس جس طریقے سے مسلمانوں کی بدر میں مدد فرمائی، اس کا بیان ہے ۔\n[2] ”بَنَانٍ“ ہاتھوں اور پیروں کے پور، یعنی ان کی انگلیوں کے اطراف (کنارے)، یہ اطراف کاٹ دیئے جائیں تو ظاہر ہے کہ وہ معذور ہو جائیں گے۔ اس طرح وہ ہاتھوں سے تلوار چلانے کے اور پیروں سے بھاگنے کے قابل نہیں رہیں گے۔",
