      "arFull": "ذٰلِكَ بِاَنَّهُمْ شَآقُّوا اللّٰهَ وَرَسُوْلَهٗ ۚ وَمَنْ یُّشَاقِقِ اللّٰهَ وَرَسُوْلَهٗ فَاِنَّ اللّٰهَ شَدِیْدُ الْعِقَابِ ۟",
