      "number": 52,
      "arFull": "كَدَاْبِ اٰلِ فِرْعَوْنَ ۙ وَالَّذِیْنَ مِنْ قَبْلِهِمْ ؕ كَفَرُوْا بِاٰیٰتِ اللّٰهِ فَاَخَذَهُمُ اللّٰهُ بِذُنُوْبِهِمْ ؕ اِنَّ اللّٰهَ قَوِیٌّ شَدِیْدُ الْعِقَابِ ۟",
      "ur": "مثل فرعونیوں کے حال کے اور ان سے اگلوں کے[1] ، کہ انہوں نے اللہ کی آیتوں سے کفر کیا پس اللہ نے ان کے گناہوں کے باعﺚ انہیں پکڑ لیا۔ اللہ تعالیٰ یقیناً قوت واﻻ اور سخت عذاب واﻻ ہے۔",
      "en": "[Theirs is] like the custom of the people of Pharaoh and of those before them. They disbelieved in the signs of Allāh, so Allāh seized them for their sins. Indeed, Allāh is Powerful and severe in penalty.",
      "footnotesUr": "[1] ”دَأْبٌ“ کے معنی ہیں عادت۔ کاف تشبیہ کے لئے ہے۔ یعنی ان مشرکین کی عادت یا حال، اللہ کے پیغمبر کے جھٹلانے میں، اسی طرح ہے جس طرح فرعون اور اس سے قبل دیگر مکذبین کی عادت یا حال تھا۔",
