      "arFull": "كَدَاْبِ اٰلِ فِرْعَوْنَ ۙ وَالَّذِیْنَ مِنْ قَبْلِهِمْ ؕ كَذَّبُوْا بِاٰیٰتِ رَبِّهِمْ فَاَهْلَكْنٰهُمْ بِذُنُوْبِهِمْ وَاَغْرَقْنَاۤ اٰلَ فِرْعَوْنَ ۚ وَكُلٌّ كَانُوْا ظٰلِمِیْنَ ۟",
