      "number": 73,
      "arFull": "وَالَّذِیْنَ كَفَرُوْا بَعْضُهُمْ اَوْلِیَآءُ بَعْضٍ ؕ اِلَّا تَفْعَلُوْهُ تَكُنْ فِتْنَةٌ فِی الْاَرْضِ وَفَسَادٌ كَبِیْرٌ ۟ؕ",
      "ur": "کافر آپس میں ایک دوسرے کے رفیق ہیں، اگر تم نے ایسا نہ کیا تو ملک میں فتنہ ہوگا اور زبردست فساد ہو جائے گا۔[1]",
      "en": "And those who disbelieved are allies of one another. If you do not do so [i.e., ally yourselves with other believers], there will be fitnah [i.e., disbelief and oppression] on earth and great corruption.",
      "footnotesUr": "[1] یعنی جس طرح کافر ایک دوسرے کے دوست اور حمایتی ہیں اسی طرح اگر تم بھی ایمان کی بنیاد پر ایک دوسرے کی حمایت اور کافروں سے عدم موالات نہ کی، تو پھر بڑا فتنہ اور فساد ہوگا۔ اور وہ یہ کہ مومن اور کافر کے باہمی اختلاط اور محبت وموالات سےدین کے معاملے میں اشتباہ اور مداہنت پیدا ہوگی۔ بعض نے ”بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ“ سے، وارث ہونا مراد لیا ہے ۔ یعنی کافر ایک دوسرے کے وارث ہیں۔ اور مطلب یہ ہے کہ ایک مسلمان کسی کافر کا اور کافر کسی مسلمان کا وارث نہیں ہے۔ جیسا کہ احادیث میں اسے وضاحت سے بیان کر دیا گیا ہے۔ اگر تم وراثت میں کفر وایمان کو نظر انداز کرکے محض قرابت کو سامنے رکھو گے تو اس سے بڑا فتنہ اور فساد پیدا ہوگا۔",
